// Unit tests for the minimal JSON parser (driver/json.hpp).
//
// The parser exists because the framework may depend only on libc++ + the
// shared ABI header -- no third-party JSON library. It must handle the engine
// descriptor shape (objects, string/number values, arrays of strings, one
// nested object) plus the usual literals and whitespace.
#include <string>

#include "json.hpp"
#include "test_check.hpp"

using namespace andes_sim;

int main() {
  // A representative engine descriptor.
  const char* doc = R"({
    "id": "verilator:ax45mpv_premium",
    "type": "verilator",
    "kind": "cycle-accurate",
    "vlen": 512, "xlen": 64,
    "triggers": ["marker", "pc", "icount"],
    "roles": ["standalone", "accurate-leg"],
    "state": ["resume", "drain"],
    "invoke": {
      "standalone": ["{bin}", "{elf}"],
      "accurate-leg": ["{bin}", "--resume-from-qemu", "{state_in}"]
    },
    "result": "stderr:cycles"
  })";

  json::Parsed p = json::parse(doc);
  CHECK(p.ok);
  CHECK(p.value.is_object());

  const json::Value& v = p.value;
  CHECK(v.find("id") != nullptr);
  CHECK(v.find("id")->as_string() == "verilator:ax45mpv_premium");
  CHECK(v.find("type")->as_string() == "verilator");
  CHECK(v.find("vlen")->is_number());
  CHECK(v.find("vlen")->as_int() == 512);
  CHECK(v.find("xlen")->as_int() == 64);
  CHECK(v.find("missing") == nullptr);

  // arrays of strings
  const json::Value* trig = v.find("triggers");
  CHECK(trig && trig->is_array());
  std::vector<std::string> trigs = trig->as_string_array();
  CHECK(trigs.size() == 3);
  CHECK(trigs[0] == "marker" && trigs[2] == "icount");

  // nested object + nested array
  const json::Value* inv = v.find("invoke");
  CHECK(inv && inv->is_object());
  const json::Value* leg = inv->find("accurate-leg");
  CHECK(leg && leg->is_array());
  CHECK(leg->as_string_array().size() == 3);
  CHECK(leg->as_string_array()[1] == "--resume-from-qemu");

  // literals + escapes + whitespace tolerance
  {
    json::Parsed q = json::parse(R"({"a":true,"b":false,"c":null,"d":-3.5})");
    CHECK(q.ok);
    CHECK(q.value.find("a")->type == json::Value::Type::Bool);
    CHECK(q.value.find("a")->b == true);
    CHECK(q.value.find("c")->type == json::Value::Type::Null);
    CHECK(q.value.find("d")->is_number());
  }
  {
    json::Parsed q = json::parse(R"("a\tb\"c")");
    CHECK(q.ok);
    CHECK(q.value.is_string());
    CHECK(q.value.str == "a\tb\"c");
  }
  {
    json::Parsed q = json::parse("   [ 1 , 2 ,3 ]  ");
    CHECK(q.ok);
    CHECK(q.value.is_array());
    CHECK(q.value.arr.size() == 3);
  }

  // malformed inputs fail (do not crash, ok=false)
  for (const char* bad : {"{", "{\"a\":}", "[1,2", "tru", "\"unterminated",
                          "{\"a\" 1}", ""}) {
    json::Parsed q = json::parse(bad);
    CHECK(!q.ok);
  }

  return andes_sim::test::report("json parse");
}

// Unit tests for the driver scaffold helpers:
//   - build_argv / shell_quote / render_argv  (driver/argv.hpp) placeholder subst
//   - ljust / join / vlen_str                 (driver/strutil.hpp) text helpers
//   - config_env_value                        (driver/config_env.hpp) env|config.env
//
// Plain assert-and-count harness (no doctest); each CHECK bumps a failure
// counter and the process exits non-zero if any failed. Run by
// tests/andes_sim/test_andes_sim_f5.sh.
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <map>
#include <string>
#include <vector>

#include <unistd.h>

#include "argv.hpp"
#include "config_env.hpp"
#include "strutil.hpp"
#include "test_check.hpp"

using namespace andes_sim;

int main() {
  // --- shell_quote: safe tokens pass through; anything else is single-quoted ---
  {
    CHECK(shell_quote("plain") == "plain");
    CHECK(shell_quote("a/b-c.d_e:1,2") == "a/b-c.d_e:1,2");
    CHECK(shell_quote("") == "''");
    CHECK(shell_quote("a b") == "'a b'");
    // an embedded single quote is escaped as '\''
    CHECK(shell_quote("it's") == "'it'\\''s'");
  }

  // --- render_argv: join an argv into one copy-pasteable, shell-quoted line ---
  {
    CHECK(render_argv({"qemu", "-m", "128M", "a b"}) == "qemu -m 128M 'a b'");
    CHECK(render_argv({}) == "");
  }

  // --- build_argv: substitute {key} from ctx into an invoke template ---
  {
    std::string err;
    const std::map<std::string, std::string> ctx = {{"bin", "/x/qemu"},
                                                    {"elf", "p.elf"},
                                                    {"mmap", "/dev/shm/f"},
                                                    {"sz", "128M"}};
    CHECK(build_argv({"{bin}", "{elf}"}, ctx, err) ==
          std::vector<std::string>({"/x/qemu", "p.elf"}));
    CHECK(err.empty());
    // more than one key in one arg, and a key used twice
    CHECK(build_argv({"path={mmap},size={sz}"}, ctx, err) ==
          std::vector<std::string>({"path=/dev/shm/f,size=128M"}));
    CHECK(build_argv({"{mmap}-{mmap}"}, ctx, err) ==
          std::vector<std::string>({"/dev/shm/f-/dev/shm/f"}));
    // an unknown placeholder is an error: {} returned, err set
    CHECK(build_argv({"{nope}"}, ctx, err).empty());
    CHECK(!err.empty());
    // an unbalanced brace is kept literally, not an error
    CHECK(build_argv({"a{b"}, ctx, err) ==
          std::vector<std::string>({"a{b"}));
    CHECK(err.empty());
  }

  // --- strutil: ljust / join / vlen_str ---
  {
    CHECK(ljust("hi", 5) == "hi   ");
    CHECK(ljust("hello", 3) == "hello");  // never truncates
    CHECK(join({"a", "b", "c"}) == "a,b,c");
    CHECK(join({"a", "b"}, ";") == "a;b");
    CHECK(join({}) == "");
    CHECK(vlen_str(512) == "512");
    CHECK(vlen_str(0) == "-");
    CHECK(vlen_str(-1) == "-");
  }

  // --- config_env_value: env wins, else the first key=value in config.env ---
  {
    char tmpl[] = "/tmp/andesim-cfg.XXXXXX";
    int fd = mkstemp(tmpl);
    CHECK(fd >= 0);
    close(fd);
    {
      std::ofstream f(tmpl);
      f << "# a per-host config line\n"
        << "  QEMU_BIN_DIR=/opt/qemu/build\n"     // leading ws tolerated
        << "VSIM_BIN_DIR=/opt/vsim/build   \n";   // trailing ws right-trimmed
    }
    const std::filesystem::path cfg = tmpl;

    // the environment wins over the file
    setenv("QEMU_BIN_DIR", "/env/qemu", 1);
    CHECK(config_env_value("QEMU_BIN_DIR", cfg) == "/env/qemu");
    // an empty env var does NOT win -- it falls through to the file
    setenv("QEMU_BIN_DIR", "", 1);
    CHECK(config_env_value("QEMU_BIN_DIR", cfg) == "/opt/qemu/build");
    unsetenv("QEMU_BIN_DIR");
    CHECK(config_env_value("QEMU_BIN_DIR", cfg) == "/opt/qemu/build");
    // value is right-trimmed; comment + missing key handled
    unsetenv("VSIM_BIN_DIR");
    CHECK(config_env_value("VSIM_BIN_DIR", cfg) == "/opt/vsim/build");
    CHECK(config_env_value("NO_SUCH_KEY", cfg).empty());

    unlink(tmpl);
    // a missing config file is not an error -- just no value
    CHECK(config_env_value("QEMU_BIN_DIR",
                           "/nonexistent/andesim-no-config.env").empty());
  }

  return andes_sim::test::report("infra");
}
